def find_Min_Swaps(arr, n):
    swaps = 0
    for i in range(n):
        if arr[i] == 1:
            continue
        j = i
        while j < n and arr[j] == 0:
            j += 1
        if j == n:
            break
        while j > i:
            arr[j], arr[j - 1] = arr[j - 1], arr[j]
            j -= 1
            swaps += 1
    return swaps
