def is_prime(num):
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def fibonacci_generator():
    a, b = 0, 1
    while True:
        yield a
        a, b = b, a + b

def prime_fib(n: int):
    fib_gen = fibonacci_generator()
    count = 0
    while count < n:
        fib_num = next(fib_gen)
        if is_prime(fib_num):
            count += 1
    return fib_num
