import math

def calculate_polygons(start_x, start_y, width, height, num_rows):
    def hex_corner(x, y, size, i):
        angle_deg = 60 * i + 30
        angle_rad = math.radians(angle_deg)
        return (x + size * math.cos(angle_rad), y + size * math.sin(angle_rad))

    def hexagon(x, y, size):
        return [hex_corner(x, y, size, i) for i in range(6)]

    size = width / 2
    polygons = []
    for row in range(num_rows):
        for col in range(2 * row + 1):
            x = start_x + col * (3 * size / 2)
            y = start_y + row * (math.sqrt(3) * size)
            if row % 2 == 1:
                x += size / 2
            polygons.append(hexagon(x, y, size))

    return polygons

